use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// Hosts this node's HTTPClient handle is scoped to. Mirrors the graph
/// declaration so that a subscription outside the scope is recorded as a
/// failure rather than trapping the whole run at the boundary.
const ALLOWED_HOSTS: &[&str] = &[
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extract the lowercase host from an http(s) URL, or None if it is not one.
fn host_of(url: &str) -> Option<String> {
    let trimmed = url.trim();
    let lower = trimmed.to_ascii_lowercase();
    let rest = if lower.starts_with("https://") {
        &trimmed[8..]
    } else if lower.starts_with("http://") {
        &trimmed[7..]
    } else {
        return None;
    };
    let authority_end = rest
        .find(|c| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..authority_end];
    let host_port = match authority.rfind('@') {
        Some(i) => &authority[i + 1..],
        None => authority,
    };
    let host = match host_port.rfind(':') {
        Some(i) => &host_port[..i],
        None => host_port,
    };
    let host = host.trim_end_matches('.');
    if host.is_empty() {
        None
    } else {
        Some(host.to_ascii_lowercase())
    }
}

fn is_allowed(url: &str) -> bool {
    match host_of(url) {
        Some(h) => ALLOWED_HOSTS.iter().any(|a| *a == h),
        None => false,
    }
}

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for url in subscriptions.urls {
            if !is_allowed(&url) {
                failures.push(FetchFailure {
                    url,
                    error: String::from("host not in this node's allowlist"),
                });
                continue;
            }
            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
